cat << 'EOF' > patch.mjs
import fs from 'fs';
const file = 'src/orchestration/chatOrchestrator.test.ts';
let code = fs.readFileSync(file, 'utf8');

code = code.replace(/let secondRoundLastMessage: any;/, 'let secondRoundLastMessage: Message | undefined;');

code = code.replace(
/if \(params\.messages\.length === 2\) \{\s+\/\/ 1 system \+ 1 user message initially, wait, maybe just check round count\s+yield \{type: 'tool_use', toolCall: \{id: '1', name: 'lookup', input: \{\}\}\};\s+yield \{type: 'stop', stopReason: 'tool_use'\};\s+\} else \{\s+secondRoundLastMessage = params\.messages\[params\.messages\.length - 1\];\s+yield \{type: 'text', text: 'corrected'\};\s+yield \{type: 'stop', stopReason: 'end_turn'\};\s+\}/,
`if (params.messages.length === 2) {
          yield {type: 'tool_use', toolCall: {id: '1', name: 'lookup', input: {}}};
          yield {type: 'stop', stopReason: 'tool_use'};
          return;
        }
        secondRoundLastMessage = params.messages[params.messages.length - 1];
        yield {type: 'text', text: 'corrected'};
        yield {type: 'stop', stopReason: 'end_turn'};`
);

code = code.replace(
/expect\(result\)\.toBe\('corrected'\);\s+expect\(secondRoundLastMessage\.role\)\.toBe\('user'\);\s+expect\(secondRoundLastMessage\.content\[0\]\.content\)\.toMatch\(\/Validation failed\.\*q\/i\);/,
`const lastContent = secondRoundLastMessage?.content;
    const contentText = Array.isArray(lastContent) ? lastContent[0]?.content : undefined;
    expect({
      result,
      role: secondRoundLastMessage?.role,
      validationFailed: /Validation failed.*q/i.test(String(contentText)),
    }).toEqual({
      result: 'corrected',
      role: 'user',
      validationFailed: true,
    });`
);

code = `import type { Message } from '../../types/ai.js';\n` + code;
fs.writeFileSync(file, code);
EOF
node patch.mjs

